#include <bits/stdc++.h>
using namespace std;

// encoded length of one run of v equal characters
static int cost(int v) { return v == 0 ? 0 : v == 1 ? 1 : (int)to_string(v).size() + 1; }

int main() {
    string s;
    int k;
    cin >> s >> k;
    int n = s.size();
    // left[i]/right[i]: run length ending/starting at i; prefix/suffix: encoded lengths
    vector<int> left(n), right(n), prefix(n + 1, 0), suffix(n + 1, 0);
    for (int i = 0; i < n; i++) {
        left[i] = i && s[i - 1] == s[i] ? left[i - 1] + 1 : 1;
        prefix[i + 1] = prefix[i] + cost(left[i]) - cost(left[i] - 1);
    }
    for (int i = n - 1; i >= 0; i--) {
        right[i] = i + 1 < n && s[i + 1] == s[i] ? right[i + 1] + 1 : 1;
        suffix[i] = suffix[i + 1] + cost(right[i]) - cost(right[i] - 1);
    }
    int answer = n;
    for (int start = 0; start + k <= n; start++) {
        int end = start + k, length = prefix[start] + suffix[end];
        // the runs on both sides of the cut merge when their letters match
        if (start && end < n && s[start - 1] == s[end])
            length += cost(left[start - 1] + right[end]) - cost(left[start - 1]) - cost(right[end]);
        answer = min(answer, length);
    }
    cout << answer << "\n";
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static String next() {
        while (buf[pos] <= ' ') pos++;
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        while (buf[pos] <= ' ') pos++;
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    // encoded length of one run of v equal characters
    static int cost(int v) {
        return v == 0 ? 0 : v == 1 ? 1 : Integer.toString(v).length() + 1;
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        String s = next();
        int k = nextInt(), n = s.length();
        // left[i]/right[i]: run length ending/starting at i; prefix/suffix: encoded lengths
        int[] left = new int[n], right = new int[n], prefix = new int[n + 1], suffix = new int[n + 1];
        for (int i = 0; i < n; i++) {
            left[i] = i > 0 && s.charAt(i - 1) == s.charAt(i) ? left[i - 1] + 1 : 1;
            prefix[i + 1] = prefix[i] + cost(left[i]) - cost(left[i] - 1);
        }
        for (int i = n - 1; i >= 0; i--) {
            right[i] = i + 1 < n && s.charAt(i + 1) == s.charAt(i) ? right[i + 1] + 1 : 1;
            suffix[i] = suffix[i + 1] + cost(right[i]) - cost(right[i] - 1);
        }
        int answer = n;
        for (int start = 0; start + k <= n; start++) {
            int end = start + k, length = prefix[start] + suffix[end];
            // the runs on both sides of the cut merge when their letters match
            if (start > 0 && end < n && s.charAt(start - 1) == s.charAt(end))
                length += cost(left[start - 1] + right[end]) - cost(left[start - 1]) - cost(right[end]);
            answer = Math.min(answer, length);
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

// encoded length of one run of v equal characters
func cost(v int) int {
	switch v {
	case 0:
		return 0
	case 1:
		return 1
	}
	return len(strconv.Itoa(v)) + 1
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var s string
	var k int
	fmt.Fscan(in, &s, &k)
	n := len(s)
	// left[i]/right[i]: run length ending/starting at i; prefix/suffix: encoded lengths
	left, right := make([]int, n), make([]int, n)
	prefix, suffix := make([]int, n+1), make([]int, n+1)
	for i := 0; i < n; i++ {
		left[i] = 1
		if i > 0 && s[i-1] == s[i] {
			left[i] = left[i-1] + 1
		}
		prefix[i+1] = prefix[i] + cost(left[i]) - cost(left[i]-1)
	}
	for i := n - 1; i >= 0; i-- {
		right[i] = 1
		if i+1 < n && s[i+1] == s[i] {
			right[i] = right[i+1] + 1
		}
		suffix[i] = suffix[i+1] + cost(right[i]) - cost(right[i]-1)
	}
	answer := n
	for start := 0; start+k <= n; start++ {
		end := start + k
		length := prefix[start] + suffix[end]
		// the runs on both sides of the cut merge when their letters match
		if start > 0 && end < n && s[start-1] == s[end] {
			length += cost(left[start-1]+right[end]) - cost(left[start-1]) - cost(right[end])
		}
		answer = min(answer, length)
	}
	fmt.Println(answer)
}
